#!/usr/bin/env python3
import sys
import csv
import json

def normalize_item(name: str) -> str:
    """Collapse all whitespace to single spaces and casefold."""
    # Split on any whitespace and join with single space
    normalized = ' '.join(name.split())
    return normalized.casefold()

def parse_quantity(q_str: str) -> int:
    """Parse quantity: blank means 1, otherwise nonnegative integer."""
    stripped = q_str.strip()
    if stripped == '':
        return 1
    return int(stripped)

def main():
    if len(sys.argv) < 2:
        print("Usage: python solution.py <input_csv_file>", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]

    # Read the CSV file
    with open(input_file, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader, None)

        # Dictionary to accumulate quantities by normalized item name
        accum = {}

        for row in reader:
            if len(row) < 2:
                continue  # Skip malformed rows

            item_raw = row[0]
            qty_raw = row[1]

            item_norm = normalize_item(item_raw)

            # Skip empty normalized names
            if item_norm == '':
                continue

            qty = parse_quantity(qty_raw)

            # Accumulate quantities
            if item_norm in accum:
                accum[item_norm] += qty
            else:
                accum[item_norm] = qty

    # Build result list sorted by normalized item name
    result = [
        {"item": name, "quantity": qty}
        for name, qty in sorted(accum.items())
    ]

    # Output exactly one JSON value to stdout
    print(json.dumps(result))

if __name__ == "__main__":
    main()
